{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "padding": {"top": 0, "bottom": 0, "left": 0, "right": 0},
  "background": "#111111",
  "signals": [
    {
      "name": "sel",
      "value": null,
      "on": [{
        "events": {"type": "click", "markname": "bg"},
        "update": "datum.t === sel ? null : datum.t",
        "force": true
      }]
    },
    {
      "name": "_kf",
      "value": null,
      "on": [{
        "events": {"type": "click", "markname": "bg"},
        "update": "datum.t === sel ? kibanaAddFilter({'match_phrase': {'omb.kex_tier': datum.t}}) : kibanaRemoveFilter({'match_phrase': {'omb.kex_tier': datum.t}})",
        "force": true
      }]
    }
  ],
  "data": [
    {
      "name": "raw",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "tychon-pqc-inventory*",
        "body": {"size": 0, "aggs": {"k": {"terms": {"field": "omb.kex_tier", "size": 20}, "aggs": {"u": {"cardinality": {"field": "process.executable"}}}}}}
      },
      "format": {"property": "aggregations.k.buckets"},
      "transform": [
        {"type": "formula", "as": "t",      "expr": "datum.key"},
        {"type": "formula", "as": "hcount", "expr": "datum.u ? datum.u.value : 0"}
      ]
    },
    {
      "name": "tc",
      "source": "raw",
      "transform": [{"type": "aggregate", "groupby": ["t"], "ops": ["sum"], "fields": ["hcount"], "as": ["n"]}]
    },
    {
      "name": "mx",
      "source": "tc",
      "transform": [{"type": "aggregate", "ops": ["max"], "fields": ["n"], "as": ["v"]}]
    },
    {
      "name": "rows",
      "values": [
        {"t": "PQC READY",  "lbl": "ML-KEM / Kyber",  "desc": "Post-quantum — harvest-proof",         "badge": "PQC READY", "clr": "#00c853", "bg": "#00c85318", "ord": 0},
        {"t": "MODERN",    "lbl": "X25519 / ECDHE",   "desc": "Elliptic curve — quantum-vulnerable",  "badge": "MODERN",    "clr": "#448aff", "bg": "#448aff18", "ord": 1},
        {"t": "CLASSICAL", "lbl": "DHE / DH",          "desc": "Finite-field DH — quantum-vulnerable", "badge": "CLASSICAL", "clr": "#ffa726", "bg": "#ffa72618", "ord": 2},
        {"t": "LEGACY",    "lbl": "RSA Key Exchange",  "desc": "No forward secrecy — deprecated",      "badge": "LEGACY",    "clr": "#ef5350", "bg": "#ef535018", "ord": 3}
      ],
      "transform": [
        {"type": "lookup", "from": "tc", "key": "t", "fields": ["t"], "values": ["n"], "as": ["n"], "default": 0},
        {"type": "formula", "as": "y", "expr": "datum.ord * 72 + 60"}
      ]
    }
  ],
  "marks": [
    {
      "type": "text",
      "encode": {"enter": {"x": {"value": 16}, "y": {"value": 18}, "text": {"value": "POST-QUANTUM CRYPTOGRAPHY READINESS"}, "fill": {"value": "#cccccc"}, "fontSize": {"value": 10}, "fontWeight": {"value": "bold"}, "font": {"value": "monospace"}, "letterSpacing": {"value": 1.5}}}
    },
    {
      "type": "text",
      "encode": {"enter": {"x": {"value": 16}, "y": {"value": 38}, "text": {"value": "KEY EXCHANGE  —  click a tier to filter"}, "fill": {"value": "#555555"}, "fontSize": {"value": 9}, "font": {"value": "monospace"}, "letterSpacing": {"value": 1}}}
    },
    {
      "type": "rule",
      "encode": {"enter": {"x": {"value": 0}, "x2": {"signal": "width"}, "y": {"value": 48}, "stroke": {"value": "#252525"}, "strokeWidth": {"value": 1}}}
    },
    {
      "type": "rect",
      "name": "bg",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 0}, "y": {"field": "y"}, "width": {"signal": "width"}, "height": {"value": 66},
        "fill": {"signal": "datum.t===sel?'#1c1c2e':datum.n>0?'#161622':'#161616'"},
        "cursor": {"value": "pointer"}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 0}, "y": {"field": "y"}, "width": {"value": 4}, "height": {"value": 66},
        "fill": {"signal": "datum.n>0?datum.clr:'#2a2a2a'"}
      }}
    },
    {
      "type": "rule",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"signal": "datum.y + 65"},
        "stroke": {"value": "#222222"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 18}, "y": {"signal": "datum.y + 24"},
        "text": {"signal": "datum.lbl"}, "limit": {"signal": "width*0.62-18"},
        "fill": {"signal": "datum.n>0?'#e8e8e8':'#444444'"},
        "fontSize": {"value": 13}, "fontWeight": {"value": "bold"}, "font": {"value": "monospace"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 18}, "y": {"signal": "datum.y + 44"},
        "text": {"signal": "datum.desc"}, "limit": {"signal": "width*0.62-18"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 10}, "font": {"value": "monospace"}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width*0.65"}, "y": {"signal": "datum.y + 8"}, "width": {"value": 82}, "height": {"value": 17}, "cornerRadius": {"value": 2},
        "fill": {"signal": "datum.n>0?datum.bg:'#1a1a1a'"},
        "stroke": {"signal": "datum.n>0?datum.clr:'#2a2a2a'"}, "strokeWidth": {"value": 1}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width*0.65+41"}, "y": {"signal": "datum.y + 20"},
        "text": {"signal": "datum.badge"},
        "fill": {"signal": "datum.n>0?datum.clr:'#383838'"},
        "fontSize": {"value": 9}, "fontWeight": {"value": "bold"}, "font": {"value": "monospace"}, "align": {"value": "center"}, "letterSpacing": {"value": 1}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width*0.65"}, "y": {"signal": "datum.y + 31"}, "width": {"value": 82}, "height": {"value": 17}, "cornerRadius": {"value": 2},
        "fill": {"signal": "'#1a1a1a'"},
        "stroke": {"signal": "'#333333'"}, "strokeWidth": {"value": 1}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width*0.65+41"}, "y": {"signal": "datum.y + 43"},
        "text": {"signal": "datum.t===sel?'SELECTED':''"},
        "fill": {"signal": "datum.t===sel?datum.clr:'#448aff'"},
        "fontSize": {"value": 9}, "fontWeight": {"value": "bold"}, "font": {"value": "monospace"}, "align": {"value": "center"}, "letterSpacing": {"value": 1}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width-10"}, "y": {"signal": "datum.y + 36"},
        "text": {"signal": "datum.n>0?(datum.n>=1000?format(datum.n,'.3~s'):format(datum.n,',')):'—'"},
        "fill": {"signal": "datum.t===sel?datum.clr:datum.n>0?'#dddddd':'#333333'"},
        "fontSize": {"value": 20}, "fontWeight": {"value": "bold"}, "font": {"value": "monospace"}, "align": {"value": "right"}
      }}
    },
    {
      "type": "text",
      "encode": {"enter": {"x": {"signal": "width/2"}, "y": {"signal": "height-8"}, "text": {"value": "↑ at the highest tier"}, "fill": {"value": "#2a2a2a"}, "fontSize": {"value": 9}, "font": {"value": "monospace"}, "align": {"value": "center"}}}
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "padding": {"top": 0, "bottom": 0, "left": 0, "right": 0},
  "background": "#111111",
  "signals": [
    {"name": "totalApps",  "update": "length(data('apps_total'))>0 ? data('apps_total')[0].n : 0"},
    {"name": "kexReady",   "update": "length(data('kex_pqc'))>0 ? data('kex_pqc')[0].n : 0"},
    {"name": "kexPct",     "update": "totalApps > 0 ? round(kexReady / totalApps * 100) : 0"},
    {"name": "kexClr",     "update": "kexPct>=90 ? '#00c853' : kexPct>=60 ? '#448aff' : kexPct>=30 ? '#ffa726' : '#ef5350'"},
    {"name": "protoReady", "update": "length(data('proto_pqc'))>0 ? data('proto_pqc')[0].n : 0"},
    {"name": "protoPct",   "update": "totalApps > 0 ? round(protoReady / totalApps * 100) : 0"},
    {"name": "protoClr",   "update": "protoPct>=90 ? '#00c853' : protoPct>=60 ? '#448aff' : protoPct>=30 ? '#ffa726' : '#ef5350'"},
    {"name": "sigReady",   "update": "length(data('sig_pqc'))>0 ? data('sig_pqc')[0].n : 0"},
    {"name": "sigPct",     "update": "totalApps > 0 ? round(sigReady / totalApps * 100) : 0"},
    {"name": "sigClr",     "update": "sigPct>=90 ? '#00c853' : sigPct>=60 ? '#448aff' : sigPct>=30 ? '#ffa726' : '#ef5350'"},
    {"name": "barW",       "update": "width * 0.62 - 18"}
  ],
  "data": [
    {
      "name": "apps_raw",
      "url": {
        "%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-inventory*",
        "body": {"size": 0, "aggs": {"v": {"cardinality": {"field": "process.executable"}}}}
      },
      "format": {"property": "aggregations.v"},
      "transform": [{"type": "formula", "as": "n", "expr": "datum.value"}]
    },
    {"name": "apps_total", "source": "apps_raw"},
    {
      "name": "kex_pqc_raw",
      "url": {
        "%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-inventory*",
        "body": {"size": 0, "aggs": {"f": {"filter": {"term": {"omb.kex_tier": "PQC READY"}}, "aggs": {"u": {"cardinality": {"field": "process.executable"}}}}}}
      },
      "format": {"property": "aggregations.f.u"},
      "transform": [{"type": "formula", "as": "n", "expr": "datum.value"}]
    },
    {"name": "kex_pqc", "source": "kex_pqc_raw"},
    {
      "name": "proto_pqc_raw",
      "url": {
        "%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-inventory*",
        "body": {"size": 0, "aggs": {"f": {"filter": {"term": {"omb.protocol_tier": "TLS 1.3"}}, "aggs": {"u": {"cardinality": {"field": "process.executable"}}}}}}
      },
      "format": {"property": "aggregations.f.u"},
      "transform": [{"type": "formula", "as": "n", "expr": "datum.value"}]
    },
    {"name": "proto_pqc", "source": "proto_pqc_raw"},
    {
      "name": "sig_pqc_raw",
      "url": {
        "%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-inventory*",
        "body": {"size": 0, "aggs": {"f": {"filter": {"term": {"omb.sig_tier": "PQC READY"}}, "aggs": {"u": {"cardinality": {"field": "process.executable"}}}}}}
      },
      "format": {"property": "aggregations.f.u"},
      "transform": [{"type": "formula", "as": "n", "expr": "datum.value"}]
    },
    {"name": "sig_pqc", "source": "sig_pqc_raw"}
  ],
  "marks": [
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 16}, "y": {"value": 22},
        "text": {"value": "APPLICATION PQC DASHBOARD"},
        "fill": {"value": "#cccccc"}, "fontSize": {"value": 11}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1.5}
      }}
    },
    {
      "type": "text",
      "encode": {"update": {
        "x": {"value": 16}, "y": {"value": 40},
        "text": {"signal": "'PQC COMPLIANCE PROGRESS  —  ' + (totalApps>=1000?format(totalApps,'.3~s'):format(totalApps,',')) + ' unique applications'"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1}
      }}
    },
    {
      "type": "rule",
      "encode": {"enter": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"value": 48},
        "stroke": {"value": "#252525"}, "strokeWidth": {"value": 1}
      }}
    },

    {
      "type": "rect",
      "encode": {"update": {
        "x": {"value": 0}, "y": {"value": 60}, "width": {"signal": "width"}, "height": {"value": 78},
        "fill": {"value": "#161616"}
      }}
    },
    {
      "type": "rect",
      "encode": {"update": {
        "x": {"value": 0}, "y": {"value": 60}, "width": {"value": 4}, "height": {"value": 78},
        "fill": {"signal": "kexClr"}
      }}
    },
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 18}, "y": {"value": 78},
        "text": {"value": "KEX COMPLIANCE"},
        "fill": {"value": "#888888"}, "fontSize": {"value": 9}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1}
      }}
    },
    {
      "type": "text",
      "encode": {"update": {
        "x": {"value": 18}, "y": {"value": 93},
        "text": {"signal": "(kexReady>=1000?format(kexReady,'.3~s'):format(kexReady,',')) + ' of ' + (totalApps>=1000?format(totalApps,'.3~s'):format(totalApps,',')) + ' applications  —  PQC READY key exchange'"},
        "fill": {"value": "#444444"}, "fontSize": {"value": 9}, "font": {"value": "monospace"}
      }}
    },
    {
      "type": "rect",
      "encode": {"update": {
        "x": {"value": 18}, "y": {"value": 106}, "width": {"signal": "barW"}, "height": {"value": 8},
        "cornerRadius": {"value": 4}, "fill": {"value": "#1e1e1e"}, "stroke": {"value": "#2a2a2a"}, "strokeWidth": {"value": 1}
      }}
    },
    {
      "type": "rect",
      "encode": {"update": {
        "x": {"value": 18}, "y": {"value": 106},
        "width": {"signal": "max(0, barW * kexPct / 100)"},
        "height": {"value": 8}, "cornerRadius": {"value": 4},
        "fill": {"signal": "kexClr"}
      }}
    },
    {
      "type": "text",
      "encode": {"update": {
        "x": {"signal": "width - 10"}, "y": {"value": 122},
        "text": {"signal": "kexPct + '%'"},
        "fill": {"signal": "kexClr"},
        "fontSize": {"value": 24}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "align": {"value": "right"}
      }}
    },

    {
      "type": "rule",
      "encode": {"enter": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"value": 138},
        "stroke": {"value": "#222222"}, "strokeWidth": {"value": 1}
      }}
    },

    {
      "type": "rect",
      "encode": {"update": {
        "x": {"value": 0}, "y": {"value": 140}, "width": {"signal": "width"}, "height": {"value": 78},
        "fill": {"value": "#161616"}
      }}
    },
    {
      "type": "rect",
