        {"t": "MODERN",     "lbl": "ECDSA (P-256 / P-384)", "desc": "Elliptic curve signature — efficient, quantum-vulnerable",        "badge": "MODERN",     "clr": "#448aff", "bg": "#448aff18", "ord": 1},
